-- Restore Dagger in the Dark (map 1095, scenario 179).
-- Spawn and text data were ported read-only from Legends of Azeroth
-- Pandaria 5.4.8 (build 18414); scripts were adapted to Legion 7.3.5.
-- Legion build 26972 DB2 confirms eight steps, criteria trees, and LFG entries 586/616.
START TRANSACTION;

-- Replace the empty/partial population with the coherent MoP scenario population.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1095;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1095;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1095;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1095;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1095;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1095;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1095;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1095;
DELETE FROM `creature` WHERE `map`=1095;
DELETE FROM `gameobject` WHERE `map`=1095;



-- Bind static and dynamically summoned scenario actors.
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_shaman' WHERE `entry`=67255;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_oracle' WHERE `entry`=67256;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_skulker' WHERE `entry`=67257;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_skinflayer' WHERE `entry`=67258;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_flesh_hunter' WHERE `entry`=67259;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_darkhatched_lizard_lord' WHERE `entry`=67263;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_broodmaster_noshi' WHERE `entry`=67264;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_rakgor_bloodrazor' WHERE `entry`=67266;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_voljin' WHERE `entry`=67414;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_mogu_rune' WHERE `entry`=67686;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_goblin_cannon' WHERE `entry`=67694;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_spring_saurok_slayer' WHERE `entry`=67706;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_stalactite' WHERE `entry`=67755;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_grizzle_gearslip' WHERE `entry`=67782;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_corrupted_dark_hatched_egg' WHERE `entry`=67798;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_corrupted_darkhatched_slayer' WHERE `entry`=67832;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_broken_mogu_tablet' WHERE `entry`=67862;
UPDATE `creature_template` SET `ScriptName`='npc_dagger_in_dark_broken_mogu_tablet' WHERE `entry`=67863;

DELETE FROM `spell_script_names` WHERE `spell_id` IN (132647,132649,133121,133548,133702,133749,133750,133752,133804);

-- MoP spell-area-trigger records map to Legion custom AreaTrigger entries.
DELETE FROM `areatrigger_scripts` WHERE `entry` IN (3684,3685,3709,3743);

DELETE FROM `creature_text` WHERE `CreatureID` IN (67263,67266,67414,67686,67748,67782,67862,67863);

ON DUPLICATE KEY UPDATE `parent`=VALUES(`parent`),`script`=VALUES(`script`),`allowMount`=VALUES(`allowMount`);

DELETE FROM `scenario_data` WHERE `MapID`=1095 OR `ScenarioID`=179;

-- Enable only after all spawn, text, script, and scenario data is installed.
DELETE FROM `disables` WHERE `sourceType`=2 AND `entry`=1095;

COMMIT;
